// ── Faders ───────────────────────────────────────────────────────
const faders = [
  { label: 'CAD CIRCLES', val: 0.28, unit: 'CIRC', fmt: v => Math.round(v * MAX_CIRCLES) + ' CIRC' },  // random circle count
  { label: 'TRIGGERS', val: 0.00, unit: 'DOTS', fmt: v => (baseDots + Math.round(v * SEQ_TOTAL)) + ' DOTS' },  // number of orange dots
  { label: 'SEQUENCER SPEED', val: 0.50, unit: 'SPEED', fmt: v => SPEED_LBL[speedIdx(v)] },   // centre (thin line) = ×1 · down = divide · up = multiply
  { label: 'PARAMETER MODULATION', val: 0.00, unit: 'MOD', fmt: v => { const n = PM_STAGES.filter(x => v > x).length; return n ? n + (n > 1 ? ' TARGETS' : ' TARGET') : 'OFF'; } },   // more = more parameters modulated
  { label: 'NOTE RANGE', val: 0.00, unit: 'RANGE', fmt: v => '×' + (1 + 2 * v).toFixed(1) + ' RANGE' },   // lane pitch spread upwards from the root (×1 … ×3)
  { label: 'PITCH RANDOM', val: 0.00, unit: 'RANDOM', fmt: v => Math.round(v * 100) + '% RANDOM' },        // per-note random scale-degree offset (up to ±7)
  { label: 'JUL', val: 0.05, unit: 'RAD'   },
  { label: 'AUG', val: 0.14, unit: 'RAD'   },
  { label: 'SEP', val: 0.27, unit: 'RAD'   },
  { label: 'OCT', val: 0.59, unit: 'AURA'  },
  { label: 'NOV', val: 0.00, unit: 'GLIDE' },
  { label: 'DEC', val: 0.17, unit: 'EDGE'  },
];
let active = 5;
let bankX = 0, bankY = 0;   // whole fader bank offset (shift+drag)

const COL  = 30;    // fader bank 30 % smaller (v47): 43 → 30
const MAXH = 179;   // 255 → 179
const DOT  = 4.5;
const BIG  = 10.5;
const PADR = 30;
const PADB = 62;

function fX(i)    { return W - PADR - faders.length * COL + i * COL + COL / 2 + bankX; }
let labelLen = 30;   // longest rotated label (px) → bank is lifted so labels stay on screen
function fBY()    { return Math.min(H - PADB + bankY, H - 24 - labelLen - 10); }
function fDotY(i) { return fBY() - faders[i].val * MAXH; }

function hitFader(mx, my) {
  const by = fBY();
  for (let i = 0; i < faders.length; i++) {
    if (Math.abs(mx - fX(i)) < COL / 2 && my > by - MAXH - BIG - 6 && my < by + 35) return i;
  }
  return -1;
}

function drawFaders() {
  ctx.save();
  ctx.font = '400 9px Inter, "Helvetica Neue", Arial, sans-serif';
  ctx.letterSpacing = '0.7px';
  labelLen = Math.max(...faders.map(f => ctx.measureText(f.label).width));
  ctx.restore();
  const by = fBY();
  faders.forEach((f, i) => {
    const x = fX(i), dy = fDotY(i);
    const isActive = i === active;
    const r = isActive ? BIG : DOT;

    ctx.beginPath();
    ctx.moveTo(x, by);
    ctx.lineTo(x, dy);
    ctx.strokeStyle = ORANGE;
    ctx.lineWidth = 1.2;
    ctx.stroke();

    if (i === 2) {   // SEQUENCER SPEED: thin black line at ×1 (centre)
      ctx.beginPath();
      ctx.moveTo(x - 6, by - MAXH * 0.5); ctx.lineTo(x + 6, by - MAXH * 0.5);
      ctx.strokeStyle = '#111'; ctx.lineWidth = 0.8; ctx.stroke();
    }

    ctx.beginPath();
    ctx.arc(x, dy, r, 0, Math.PI * 2);
    ctx.fillStyle = ORANGE;
    ctx.fill();

    ctx.save();
    ctx.translate(x, by + 17);
    ctx.rotate(-Math.PI / 2);
    ctx.font = '400 9px Inter, "Helvetica Neue", Arial, sans-serif';
    ctx.letterSpacing = '0.7px';
    ctx.fillStyle = INK;
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    ctx.fillText(f.label, 0, 0);
    ctx.restore();

    if (isActive) {
      ctx.save();
      ctx.translate(x, dy - r - 8);
      ctx.rotate(-Math.PI / 2);
      ctx.font = '400 9px Inter, "Helvetica Neue", Arial, sans-serif';
      ctx.letterSpacing = '0.7px';
      ctx.fillStyle = INK;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.fillText(f.fmt ? f.fmt(f.val) : Math.round(f.val * 100) + ' ' + f.unit, 0, 0);
      ctx.restore();
    }
  });
}

