  for (let i = SEQ_ALL.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [SEQ_ALL[i], SEQ_ALL[j]] = [SEQ_ALL[j], SEQ_ALL[i]]; }
