// A dot fires its lane when it passes 12 o'clock. Every dot sits on a slot (its old angle, quantised).
// Some dots run at 2× → they overtake others in the same lane = a "meeting" (event hook: onMeet).
const LANE_SLOTS = [16, 24, 32, 48, 64, 96, 128, 192, 256];      // beats per cycle: 4 6 8 12 16 24 32 48 64
const SPEEDS    = [1/4, 1/3, 1/2, 2/3, 1, 3/2, 2, 3, 4];
