// RHYTHM button 2 · STRAIGHT: 3-based lane cycles → nearest straight one (24→16, 48→32, 96→64, 192→128)
// and SEQUENCER SPEED snapped to the nearest power of two (÷3→÷4, ×2/3→÷2, ×3/2→×2, ×3→×4)
const STRAIGHT_SLOTS = [16, 16, 32, 32, 64, 64, 128, 128, 256];
const laneS = li => RHY.straight ? STRAIGHT_SLOTS[li] : LANE_SLOTS[li];
