let transX = 0, transY = 0;   // shift+drag offset
const T_SQ = 48, T_TRI_W = 63, T_GAP = 19;
function tPos() { return { x: 60 + transX, y: H - PADB - 16 + transY }; }   // top-left
const K_R = 22;   // BPM knob radius
let bpm = 120, panelOpen = false;
function knobPos() { const { x, y } = tPos(); return { x: x + T_SQ + T_GAP + T_TRI_W + 26 + K_R, y: y + T_SQ / 2 }; }
function synthDotPos() { const k = knobPos(); return { x: k.x + K_R + 120, y: k.y }; }
