  const g = c.getContext('2d'), W = c.width, H = c.height, T = Math.max(0.05, (SYN.envA + SYN.envD) * 1.25);
  const top = Math.max(1, SYN.index + SYN.envAmt), yv = v => H - 8 - (v / top) * (H - 16), xt = s => 8 + (s / T) * (W - 16);
